# Pointer-free panel helpers ("panel press"): the panel's own button handler is run from inside the game.
#   . tools/dev/np.sh        (sources env.sh; set LANE first for a parallel lane)
# openb <type> [nth] [host|friend] | openb xy <x> <y> [who]   open a building's panel (the player's own buildings)
# tab <n> [who]            press the nth main tab          names [who]   list the named controls of the open panel
# ptree [who] / sub <widget name> [who] / props <class> [who]             look inside the open panel
# press <name> [who] [function]     run a named widget's click event (or another of its functions)
# pressin <parent> <name> [who]     the same, inside a named parent
# call <name> <function> <lua args> [who]   callc <class> <nth> <function> <lua args> [who]   gcall <class> <function> <args> [who]
# slide <slider name> <0..1> [who]  a slider's own value-changed and release events
# apress <button name> <squad number> [who]   select the squad the game's way, then press an army command button
. "$(dirname "${BASH_SOURCE[0]:-$0}")/env.sh"
openb() { # openb <type> <nth> <who>   or  openb xy <x> <y> <who>
  if [ "$1" = "xy" ]; then printf 'pcall(function() lord:deselect_buildings() end)\nlocal b = bAt(%s, %s); if not b then return "none" end\nlord:openBuildingTab(b, false)\nreturn "opened " .. bkey(b)\n' "$2" "$3" > "$RUN/_open.lua"; on "${4:-host}" "$RUN/_open.lua" 10
  else printf 'pcall(function() lord:deselect_buildings() end)\nlocal b; local n = 0; for _, x in ipairs(buildings()) do if x:GetType() == %s and mine(x) then n = n + 1; if n == %s then b = x end end end\nif not b then return "none" end\nlord:openBuildingTab(b, false)\nreturn "opened " .. bkey(b)\n' "$1" "${2:-1}" > "$RUN/_open.lua"; on "${3:-host}" "$RUN/_open.lua" 10; fi; /usr/bin/sleep 0.8; }
ptree() { on "${1:-host}" "$DEV/lua/t_ptree.lua" 20; }
press() { # press <widget name> [host|friend] [function name]
  printf 'local p = panel(); if not p then return "no panel" end\nlocal w = find(p, "%s"); if not w then return "not found: %s" end\nlocal fn = "%s"; if fn == "" then fn = CLICK end\nlocal ok, e = pcall(function() w[fn](w) end)\nreturn "pressed %s (" .. cname(w) .. "): " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "${3:-}" "$1" > "$RUN/_press.lua"; on "${2:-host}" "$RUN/_press.lua" 10; }
last() { echo "host sent: $(grep "TOWN sent\|O [A-Z]* \| sent to" "$LK/host_log.txt" | tail -1 | cut -c16-150)"; echo "friend:    $(grep "TOWN APPLIED\|TOWN FAILED\|TOWN sent\|refus" "$LK/friend1_log.txt" | tail -1 | cut -c16-150)"; echo "host got:  $(grep "TOWN APPLIED\|TOWN FAILED\|APPLIED" "$LK/host_log.txt" | tail -1 | cut -c16-150)"; }
slide() { # slide <slider name> <value> [host|friend]: the slider's own value-changed event, then its mouse-release event
  printf 'local p = panel(); if not p then return "no panel" end\nlocal w = find(p, "%s"); if not w then return "not found: %s" end\nlocal before = "?"; pcall(function() before = tostring(w:GetValue()) end)\nlocal ok, e = pcall(function() w.SliderControl:SetValue(%s); w:BndEvt__MLDefaultSlider_SliderControl_K2Node_ComponentBoundEvent_0_OnFloatValueChangedEvent__DelegateSignature(%s); w:BndEvt__MLDefaultSlider_SliderControl_K2Node_ComponentBoundEvent_1_OnMouseCaptureEndEvent__DelegateSignature() end)\nlocal after = "?"; pcall(function() after = tostring(w:GetValue()) end)\nreturn "slid %s " .. before .. " -> " .. after .. ": " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "$2" "$2" "$1" > "$RUN/_slide.lua"; on "${3:-host}" "$RUN/_slide.lua" 10; }
tsent() { echo "  host log:   $(grep "TOWN sent\|TOWN APPLIED\|TOWN FAILED" "$LK/host_log.txt" | tail -${1:-1} | cut -c16-130 | tr '\n' ';')"; echo "  friend log: $(grep "TOWN sent\|TOWN APPLIED\|TOWN FAILED\|refus" "$LK/friend1_log.txt" | tail -${1:-1} | cut -c16-130 | tr '\n' ';')"; }
tab() { # tab <n> [host|friend]: press the nth main tab of the open panel (1-based)
  printf 'local p = panel(); if not p then return "no panel" end\nlocal sel = find(p, "HorizontalRadioSelect_MainTabs"); if not sel then return "no tabs" end\nlocal n = 0; local hit\nfor _, e in ipairs(under(sel, 8)) do if cname(e.w) == "W_InventoryRadioButton_C" and shown(e.w) then n = n + 1; if n == %s then hit = e.w end end end\nif not hit then return "tab %s not found (" .. n .. " tabs)" end\nlocal btn = find(hit, "Button", "W_MaterialButton_C") or hit\nlocal ok, e = pcall(function() btn[CLICK](btn) end)\nreturn "tab %s: " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "$1" > "$RUN/_tab.lua"; on "${2:-host}" "$RUN/_tab.lua" 10; /usr/bin/sleep 0.6; }
names() { # names [host|friend]: named, shown controls of the open panel (buttons, checkboxes, sliders, spinners, combo boxes), one line
  on "${1:-host}" "$DEV/lua/t_names.lua" 20; }
call() { # call <widget name> <function> <args as Lua, may be empty> [host|friend]: find a shown widget by name in the open panel and call one of its own functions
  printf 'local p = panel(); if not p then return "no panel" end\nlocal w = find(p, "%s"); if not w then return "not found: %s" end\nlocal ok, e = pcall(function() return w["%s"](w%s) end)\nreturn "%s.%s: " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "$2" "${3:+, $3}" "$1" "$2" > "$RUN/_call.lua"; on "${4:-host}" "$RUN/_call.lua" 10; }
callc() { # callc <class> <nth> <function> <args> [host|friend]: nth shown widget of a class in the open panel
  printf 'local p = panel(); if not p then return "no panel" end\nlocal n = 0; local w\nlocal function walk(x, d) if w or d > 40 or not shown(x) then return end; if cname(x) == "%s" then n = n + 1; if n == %s then w = x; return end end\n local okN, c = pcall(function() return x:GetChildrenCount() end)\n if okN and type(c) == "number" then for i = 0, c - 1 do local k = x:GetChildAt(i); if k and k:IsValid() then walk(k, d + 1) end end; return end\n local okC, k = pcall(function() return x:GetContent() end); if okC and k and k:IsValid() then walk(k, d + 1); return end\n local okT, r = pcall(function() return x.WidgetTree.RootWidget end); if okT and r and r:IsValid() and cname(x):sub(1, 3) ~= "MD_" then walk(r, d + 1) end end\nwalk(p, 0)\nif not w then return "no %s number %s (found " .. n .. ")" end\nlocal ok, e = pcall(function() return w["%s"](w%s) end)\nreturn "%s#%s.%s: " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$2" "$1" "$2" "$3" "${4:+, $4}" "$1" "$2" "$3" > "$RUN/_callc.lua"; on "${5:-host}" "$RUN/_callc.lua" 10; }
pressin() { # pressin <parent widget name> <name> [host|friend]: press a named widget inside a named parent of the open panel
  printf 'local p = panel(); if not p then return "no panel" end\nlocal par = find(p, "%s"); if not par then return "parent not found: %s" end\nlocal w = find(par, "%s"); if not w then return "not found in parent: %s" end\nlocal ok, e = pcall(function() w[CLICK](w) end)\nreturn "pressed %s/%s: " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "$2" "$2" "$1" "$2" > "$RUN/_pin.lua"; on "${3:-host}" "$RUN/_pin.lua" 10; }
props() { printf 'local CLS = "%s"\n' "$1" > "$RUN/_props.lua"; cat "$DEV/lua/t_props.lua" >> "$RUN/_props.lua"; on "${2:-host}" "$RUN/_props.lua" 15; }
gcall() { # gcall <class> <function> <args> [host|friend]: last visible instance of a class anywhere on screen, call one of its own functions
  printf 'local w; local n = 0\nfor _, x in ipairs(FindAllOf("%s") or {}) do if x:IsValid() then local okV, v = pcall(function() return x:IsVisible() end); if okV and v then w = x; n = n + 1 end end end\nif not w then return "no visible %s" end\nlocal ok, e = pcall(function() return w["%s"](w%s) end)\nreturn "%s (" .. n .. " visible).%s: " .. tostring(ok) .. " " .. tostring(e)\n' "$1" "$1" "$2" "${3:+, $3}" "$1" "$2" > "$RUN/_gcall.lua"; on "${4:-host}" "$RUN/_gcall.lua" 10; }
apress() { # apress <button name> <squad number> [host|friend]: select the squad the game's own way, then press a button of the live army command list
  printf 'pcall(function() lord:selectSquad({ Value = %s }, true, false) end)\nlocal hit\nfor _, cls in ipairs({ "W_HUD_ArmyStanceButtonV2_C", "W_HUD_ArmySkillButtonV2_C" }) do for _, w in ipairs(FindAllOf(cls) or {}) do if w:IsValid() and w:GetFName():ToString() == "%s" then local o = "?"; pcall(function() o = w:GetOuter():GetOuter():GetFName():ToString() end); if o == "CommandList" then hit = w end end end end\nif not hit then return "button not found: %s" end\nlocal ok, e = pcall(function() hit[CLICK](hit) end)\nreturn "pressed %s: " .. tostring(ok) .. " " .. tostring(e)\n' "$2" "$1" "$1" "$1" > "$RUN/_apress.lua"; on "${3:-host}" "$RUN/_apress.lua" 10; }
olast() { echo "  host: $(grep "APPLIED friend1 [0-9]* [A-Z]" "$LK/host_log.txt" | tail -1 | cut -c16-110)"; }

sub() { printf 'local SUBNAME = "%s"
' "$1" > "$RUN/_sub.lua"; cat "$DEV/lua/t_sub.lua" >> "$RUN/_sub.lua"; on "${2:-host}" "$RUN/_sub.lua" 20; }
